example_queries:
PREFIX ex: <http://ex/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?expedition ?startYear (COUNT(?p) AS ?crew) WHERE {
  ?e ex:participant ?p ; rdfs:label ?expedition ; ex:startYear ?startYear .
} GROUP BY ?expedition ?startYear ORDER BY DESC(?crew)

PREFIX ex: <http://ex/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
CONSTRUCT {
  wd:Q973919 ?p ?o . ?o rdfs:label ?name .
} WHERE {
  wd:Q973919 ?p ?o .
  FILTER(?p = ex:leader || ?p = ex:vessel || ?p = ex:participant)
  ?o rdfs:label ?name .
}

PREFIX ex: <http://ex/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?year ?expedition WHERE { ?e ex:startYear ?year ; rdfs:label ?expedition }
